421	     * Return this owner's check digit: the single Luhn check digit computed over the
422	     * digits of the {@link #getCustomerCode() customer code}.
423	     */
424	    @Transient
425	    public int getCheckDigit() {
426	        return LuhnCheckDigit.of(this.customerCode);
427	    }
428	
429	    /**
430	     * Return this owner's preferred contact channel: {@code EMAIL} when an
431	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
432	     */
433	    @Transient
434	    public String getContactPreference() {
435	        boolean hasEmail = this.email != null && !this.email.isEmpty();
436	        return hasEmail ? "EMAIL" : "PHONE";
437	    }
438	
439	    /**
440	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
441	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
442	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
443	     */
444	    @Transient
445	    public String getAgeBand() {
446	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
447	        return ageBand == null ? null : ageBand.name();
448	    }
