450	    protected Set<Pet> getPetsInternal() {
451	        if (this.pets == null) {
452	            this.pets = new HashSet<>();
453	        }
454	        return this.pets;
455	    }
456	
457	    protected void setPetsInternal(Set<Pet> pets) {
458	        this.pets = pets;
459	    }
