462	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
463	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
464	        return Collections.unmodifiableList(sortedPets);
465	    }
466	
467	    public void setPets(List<Pet> pets) {
468	        this.pets = new HashSet<>(pets);
469	    }
470	
471	    public void addPet(Pet pet) {
472	        getPetsInternal().add(pet);
473	        pet.setOwner(this);
474	    }
475	
476	    /**
477	     * Return the Pet with the given name, or null if none found for this Owner.
478	     *
479	     * @param name to test
480	     * @return true if pet name is already in use
481	     */
482	    public Pet getPet(String name) {
483	        return getPet(name, false);
484	    }
485	
486	    /**
487	     * Return the Pet with the given name, or null if none found for this Owner.
488	     *
489	     * @param name to test
490	     * @return true if pet name is already in use
491	     */
492	    public Pet getPet(String name, boolean ignoreNew) {
493	        name = name.toLowerCase();
494	        for (Pet pet : getPetsInternal()) {
495	            if (!ignoreNew || !pet.isNew()) {
496	                String compName = pet.getName();
497	                compName = compName.toLowerCase();
498	                if (compName.equals(name)) {
499	                    return pet;
500	                }
501	            }
502	        }
503	        return null;
504	    }
505	
506	    public Pet getPet(Integer petId) {
507	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
508	    }
509	
510	    @Override
511	    public String toString() {
512	        return new ToStringCreator(this)
513	
514	            .append("id", this.getId())
515	            .append("new", this.isNew())
516	            .append("lastName", this.getLastName())
517	            .append("firstName", this.getFirstName())
518	            .append("address", this.address)
519	            .append("city", this.city)
520	            .append("telephone", this.telephone)
521	            .append("email", this.email)
522	            .toString();
523	    }
524	}
