package org.springframework.samples.petclinic.model;

import java.util.Map;

/**
 * Fixed lookup of a region to its IANA timezone name.
 */
public final class RegionTimezones {

    private static final Map<String, String> REGION_TO_TIMEZONE = Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    private RegionTimezones() {
    }

    /**
     * Return the IANA timezone name for the given region, or {@code null} when the
     * region has no known timezone.
     *
     * @param region the canonical region (see {@link CityRegions})
     * @return the matching IANA timezone name, or {@code null} when the region is not in the table
     */
    public static String timezoneOf(String region) {
        return REGION_TO_TIMEZONE.get(region);
    }
}

/*
